import{_ as e,o as a,c as o,a3 as i}from"./chunks/framework.DMtjdCb-.js";const d="/help/assets/collection-detail.ja.Vl55iHzu.png",l="/help/assets/external-folders.ja.Da-enNL5.svg",r="/help/assets/collection-editions.ja.CYaJmQ9P.png",s="/help/assets/relationship-graph.ja.DPXJUuPt.png",u=JSON.parse('{"title":"7. 既存のコレクション","description":"","frontmatter":{},"headers":[],"relativePath":"ja/collections.md","filePath":"ja/collections.md"}'),n={name:"ja/collections.md"};function c(h,t,p,m,g,_){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="_7-既存のコレクション" tabindex="-1">7. 既存のコレクション <a class="header-anchor" href="#_7-既存のコレクション" aria-label="Permalink to &quot;7. 既存のコレクション&quot;">​</a></h1><p>保存済みの動画は、既存のフォルダー構成を保ったまま接続できます。一般的な作品名フォルダー、深い階層、DVD・BD や複数グループの版を認識し、再生時に再生元と版を選択できます。</p><h2 id="接続方法を選ぶ" tabindex="-1">接続方法を選ぶ <a class="header-anchor" href="#接続方法を選ぶ" aria-label="Permalink to &quot;接続方法を選ぶ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目的</th><th>使用する設定</th></tr></thead><tbody><tr><td>既存の保存先から閲覧・再生する</td><td><strong>外部の読み取り専用ライブラリをマップ</strong></td></tr><tr><td>AnimeMachine で新しいダウンロードを整理する</td><td><strong>アニメライブラリのパス</strong></td></tr><tr><td>Ani-RSS で取得した動画を使う</td><td>メディアフォルダーまたはリモートメディア機能</td></tr></tbody></table><p>既存の動画が多い場合は、読み取り専用で接続して認識と再生を確認してから、必要な整理操作を選べます。</p><h2 id="保存済みのフォルダーを追加する" tabindex="-1">保存済みのフォルダーを追加する <a class="header-anchor" href="#保存済みのフォルダーを追加する" aria-label="Permalink to &quot;保存済みのフォルダーを追加する&quot;">​</a></h2><ol><li><strong>設定 → 接続</strong> を開きます。</li><li><strong>外部の読み取り専用ライブラリをマップ</strong> を有効にし、アプリからアクセスできるフォルダーを指定します。</li><li>保存し、バックグラウンドの走査を待ちます。</li><li>その中の作品を検索し、詳細の再生元と話数を確認します。</li></ol><p><img src="'+d+'" alt="既存の動画：認識された再生元と話数" loading="lazy"></p><p>走査はサブフォルダーも対象にし、本編と NCOP・NCED・予告などを区別します。作品・シーズン・話数を識別できる名前を使い、曖昧な場合は詳細の対応作品を確認します。</p><h2 id="docker-folders" tabindex="-1">NAS とコンテナーのパス <a class="header-anchor" href="#docker-folders" aria-label="Permalink to &quot;NAS とコンテナーのパス {#docker-folders}&quot;">​</a></h2><p>Docker では先に NAS のフォルダーをコンテナーへマウントし、設定欄にはコンテナー側のパスを入力します。</p><table tabindex="0"><thead><tr><th>NAS のフォルダー</th><th>コンテナーのパス</th><th>設定に入力する値</th></tr></thead><tbody><tr><td><code>/volume1/anime</code></td><td><code>/External</code></td><td><code>/External</code></td></tr><tr><td>プロジェクトの <code>library</code></td><td><code>/Library</code></td><td><code>/Library</code></td></tr></tbody></table><p><img src="'+l+'" alt="フォルダー対応：NAS の保存先とコンテナーのパス" loading="lazy"></p><p>標準構成では <code>compose.yaml</code> と同じ場所に <code>.env</code> を作り、保存済みの動画フォルダーを指定します。</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ANM_EXTERNAL_LIBRARY_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/volume1/anime</span></span></code></pre></div><p>同じ場所で <code>docker compose up -d</code> を実行し、AnimeMachine で外部ライブラリを有効にします。<code>/volume1/anime</code> は例なので、NAS のファイル管理画面にある実際のパスへ置き換えます。</p><p>Windows では <code>C:\\Anime</code> や <code>\\\\NAS\\Anime</code> を直接指定できます。共有フォルダーは AnimeMachine の実行アカウントからアクセスできる必要があります。各パスの下に読み取り・休止状態を表示します。変更後は保存して確認します。</p><h2 id="再生する版を選ぶ" tabindex="-1">再生する版を選ぶ <a class="header-anchor" href="#再生する版を選ぶ" aria-label="Permalink to &quot;再生する版を選ぶ&quot;">​</a></h2><ol><li>認識された作品の詳細を開きます。</li><li>再生元を選び、版のプルダウンからグループ、DVD・BD、画質などを選択します。</li><li>利用できる話数を確認し、プレーヤーを開きます。</li></ol><p><img src="'+r+'" alt="版の選択：DVD・BD・グループの違いを確認" loading="lazy"></p><p><strong>確認する状態：</strong> 選んだ版の話数が表示され、その版を再生できます。「自動選択」は各話で利用できる版を選びます。</p><h2 id="保存済みのファイルが表示されない" tabindex="-1">保存済みのファイルが表示されない <a class="header-anchor" href="#保存済みのファイルが表示されない" aria-label="Permalink to &quot;保存済みのファイルが表示されない&quot;">​</a></h2><p>初回走査中は再生欄に索引の準備状態が表示されます。完了後も不足する場合は <strong>設定 → 接続</strong> でパス・マウント・読み取り状態を確認し、作品名とファイル名を確認します。休止時間や一時的な切断中も索引を保持し、アクセス可能になると再開します。</p><h2 id="シリーズのつながりを確認" tabindex="-1">シリーズのつながりを確認 <a class="header-anchor" href="#シリーズのつながりを確認" aria-label="Permalink to &quot;シリーズのつながりを確認&quot;">​</a></h2><p>作品カードの <strong>作品関連図</strong> から、前作、続編、劇場版、番外編を確認できます。開くと選択した作品の位置が表示され、図中のタイトルから詳細を開けます。関係の種類ごとの表示切り替え、全画面表示、画像の保存にも対応しています。</p><p><img src="'+s+'" alt="作品関連図" loading="lazy"></p>',26)])])}const k=e(n,[["render",c]]);export{u as __pageData,k as default};
